# -*- coding: utf-8 -*-
"""大题批次1（33 题）：「参考答案」-> 「题目解析 + 标准答案」（代码题附完整代码）。
用法：python D:\\dev-tools\\apply_big_batch.py D:\\dev-tools\\batch_big_1_data.py"""
NEW = {
    6: ("Y 型铁轨的竖直段就是一个'栈'：左轨按 1~N 顺序把车厢推入（push），右轨相当于弹栈（pop），'不允许走重复路径'保证每节车厢恰好经过一次，因此右边能形成的排列就是 1~N 的全部合法出栈序列。判定两条路：①栈模拟——按候选序列扫描，需要时把下一节车厢压栈、栈顶等于当前待输出车厢就弹出，能完整走完即合法；②模式判定——合法出栈序列不出现 312 模式（先输出较大的 b、再输出较小的 a、最后输出介于两者之间的 c，即 a<c<b）。合法序列总数是卡特兰数 C(2N,N)/(N+1)：N=1~4 依次为 1、2、5、14 种；N=3 时 6 个排列中只有 312 非法、合法 5 种（123、132、213、231、321）。易错点：把'列出全部排法'答成'某一种固定排法'；漏掉 312 模式或总数公式。", "结论：右边所有可能的排法就是 1~N 的全部合法出栈序列（把 Y 型铁轨的竖直段看作栈），总数为卡特兰数 C(2N,N)/(N+1)；例如 N=3 时共 5 种（123、132、213、231、321，312 非法）。\n枚举与判定的完整程序如下（读入 N，按字典序输出全部合法序列）：\n```c\n#include <stdio.h>\n\n#define MAXN 12\n\nstatic int n;\nstatic int seq[MAXN];              /* 当前排列 */\nstatic int used[MAXN];             /* 车厢是否已用 */\n\n/* 判定 out 是否为 1..n 的合法出栈序列：栈模拟 */\nstatic int valid(const int *out)\n{\n    int stack[MAXN], top = 0;\n    int next = 1;                  /* 下一个待入栈车厢号 */\n    for (int i = 0; i < n; i++)\n    {\n        while (next <= out[i])     /* 把 <= 当前输出值的车厢都压栈 */\n            stack[top++] = next++;\n        if (top > 0 && stack[top - 1] == out[i])\n            top--;                 /* 栈顶正是当前车厢：弹出 */\n        else\n            return 0;              /* 否则该序列非法 */\n    }\n    return 1;\n}\n\n/* 回溯枚举 1..n 的所有排列，合法的按字典序输出 */\nstatic void dfs(int pos)\n{\n    if (pos == n)\n    {\n        if (valid(seq))\n        {\n            for (int i = 0; i < n; i++)\n                printf(\"%d%c\", seq[i], i + 1 == n ? '\\n' : ' ');\n        }\n        return;\n    }\n    for (int v = 1; v <= n; v++)\n    {\n        if (!used[v])\n        {\n            used[v] = 1;\n            seq[pos] = v;\n            dfs(pos + 1);\n            used[v] = 0;\n        }\n    }\n}\n\nint main(void)\n{\n    printf(\"Input N (1-8): \");\n    if (scanf(\"%d\", &n) != 1 || n < 1 || n > 8)\n        return 1;\n    dfs(0);\n    return 0;\n}\n```\n要点：①合法性判定用栈模拟、O(N)；②全排列枚举 O(N!) 仅适合小 N，面试口答时可只给判定方法；③总数可用卡特兰数公式自检。"),
    7: ("串并转换的关键是'两级寄存器'的分工：第一级 8 个 D 触发器在 SerClk 每个有效沿采入 SerIn 并逐位移动（先入数据移向高位还是低位取决于移位方向定义），连续 8 个 SerClk 收满一个字节；第二级 8 个 D 触发器在 ParClk 有效时把移位寄存器当前的 8 位值一次并行锁存、稳定送到 ParDataOut。为什么要两级：移位期间移位寄存器内容一直在变，直接输出会出现中间态；加一级输出锁存后只在 ParClk 时刻把收满的字节搬出去，输出在整帧期间稳定。时序要求：ParClk 必须在 8 位收满之后、且满足建立/保持时间给出。易错点：把 16 个触发器都说成移位寄存器；漏掉'8 位收满后再并行锁存'的分工。", "该模块实现 8 位串行数据到并行数据的转换（串转并）。工作过程：①第一级 8 个 D 触发器接成 8 位移位寄存器，在 SerClk 的每个有效沿把 SerIn 上的一位数据逐位移入，8 个 SerClk 周期收满一个字节；②第二级 8 个 D 触发器作为输出寄存器，在 ParClk 有效时把移位寄存器当前的 8 位值一次性并行锁存并输出到 ParDataOut。两级寄存的作用：移位期间输出保持稳定、避免出现中间态；ParClk 应在移位完成后并满足建立/保持时间给出。"),
    8: ("电路由两段组成：RC 低通网络先对输入 A 做'去毛刺'滤波——窄干扰脉冲被电容吸收、跳变边沿被减缓；两级串联 D 触发器再用同一时钟对滤波结果连续打两拍——第一级把异步输入与本地时钟对齐（可能进入亚稳态），第二级给足一个时钟周期让亚稳态衰减到确定值、抑制其向下游传播；同时要求输入电平至少稳定两个时钟周期才被确认，窄毛刺被彻底滤除，输出 C 的跳变被对齐到时钟沿。占空比分情况：只要 A 上有被滤除的窄脉冲、或 A 的跳变未对齐时钟沿（被吞或按整拍变化），C 的脉宽就与 A 不同、占空比随之变化；只有 A 无毛刺、各电平远宽于一个时钟周期且与时钟同步时，C 与 A 的占空比才基本相同。易错点：把'同步纠正'答成'分频'；误认为占空比一定不变。", "(b) 工作原理：输入 A 先经 RC 低通滤波去除窄毛刺、减缓跳变边沿；再经两级串联 D 触发器在同一时钟下连续打两拍——第一级把输入与本地时钟同步（可能出现亚稳态），第二级提供完整时钟周期让亚稳态衰减、防止其传播，输入须稳定两个时钟周期才被确认，因此输出去除了毛刺、只在信号稳定后随时钟沿翻转。(c) 占空比通常不相同：①被滤除的窄脉冲改变了高低电平的持续时间；②所有跳变被对齐到时钟沿并延迟约两个时钟周期、脉宽按整拍变化（可能多落一拍）；只有输入无毛刺、电平足够宽且与时钟同步时，两者占空比才基本相同。"),
    29: ("要点是把地址当指针用：'常数→指针'必须显式强制类型转换，再解引用赋值；因为该地址是硬件寄存器/内存映射地址，内容随时可能变化、写入也不能被编译器优化掉或缓存，所以指针必须加 volatile。附带约束：①地址要按数据手册确认在有效可写范围（本题假定 0x67a9 合法）；②访问宽度由指针类型决定，用 uint32_t 指针更严谨地表达 32 位访问；③未对齐访问在 ARM 上可能触发 HardFault；④内核/裸机中通常用 writel(val, addr) 等访问器函数而不是裸指针。易错点：忘记强制转换（常数不能直接解引用）；漏掉 volatile；不说明访问宽度/对齐问题。", "核心写法：`*(volatile int *)0x67a9 = 0xaa66;`\n完整函数示例：\n```c\n/* 把绝对地址 0x67a9 处的整型变量赋值为 0xaa66（假定该地址合法可写） */\nvoid set_value_at_fixed_addr(void)\n{\n    *(volatile int *)0x67a9 = 0xaa66;   /* 强制转换为指针后解引用赋值 */\n}\n```\n说明：①volatile 必不可少——该地址为硬件寄存器/内存映射位置，禁止编译器优化或缓存该访问；②访问宽度由指针类型决定，需要 32 位访问时可写 `*(volatile uint32_t *)0x67a9 = 0xaa66u;`；③驱动中地址应来自数据手册或 ioremap，并用 writel 等访问器函数；④未对齐访问在 ARM 上可能触发 HardFault。"),
    32: ("宏是文本替换，坑全在优先级与副作用：①外层必须整体加括号，否则 `2*MAX(1,3)` 展开成 `2*1>3?1:3` 被优先级打乱；②每个参数都要加括号，否则 `MAX(1 & 3, 0)` 中 `&` 优先级低于 `>` 会算错；③参数在宏体中出现两次，`MAX(i++, j)` 会多次自增、结果错误，带副作用的实参不能用宏；④更安全的替代是 `static inline int max(int a, int b) { return a > b ? a : b; }`（C++ 可用模板或 std::max）。易错点：漏括号（本题最大扣分点）；把宏当函数理解。", "判断两个数的大小（以取较大值为例）：\n```c\n#define MAX(a, b) ((a) > (b) ? (a) : (b))   /* 取较大值；取小值把 > 改为 < */\n```\n要点：①整个表达式加外层括号、每个参数加括号，保证任何上下文展开后优先级正确；②宏参数会被求值两次，`MAX(i++, j)` 这类带副作用的实参会出错；③工程上更安全的写法：`static inline int max(int a, int b) { return a > b ? a : b; }`（C++ 用 std::max）。"),
    33: ("位操作原理都基于'掩码只选中 bit3'：`1 << 3` 生成 0x08（只有 bit3 为 1）。置位用'或'——0|x=x、1|x=1，其它位与 0 相或保持不变、bit3 变 1；清位用'与上掩码取反'——`~(1 << 3)` = 0xF7，其它位与 1 相与不变、bit3 与 0 相与变 0。a 是文件内 static 变量、两个函数直接访问；若 a 可能被中断服务程序同时修改，读—改—写过程要加临界区保护；掩码写 `1u << 3` 更规范（避免有符号移位歧义）。易错点：清位写成 `a &= (1 << 3)`（其它位会被全清零）；置位/清位运算符用错。", "两个函数如下：\n```c\nstatic int a;\n\nvoid set_bit3(void)   { a |= (1 << 3); }    /* 置位：与 1 相或，其它位不变 */\nvoid clear_bit3(void) { a &= ~(1 << 3); }   /* 清位：与取反后的掩码相与，其它位不变 */\n```\n说明：`1 << 3` = 0x08 只选中 bit3；置位靠'或'、清位靠'与掩码取反'，均保持其它位不变。a 是文件内 static 变量、函数直接访问；若 a 可能被中断同时修改，读—改—写需加临界区保护；掩码写 `1u << 3` 更规范。"),
    50: ("'标准'宏的含义是任何上下文展开都不出错：外层括号管住整个三目表达式、每个参数的括号管住代入后的表达式，缺任一个都可能在调用处被优先级改变含义（如 `2*MIN(3,4)` 不写全括号会算错）。宏是文本替换、参数出现两次——`MIN(i++, j)` 会多次自增、结果错误，这是宏相对函数的固有劣势；C 可用 `static inline` 函数替代、C++ 直接用 std::min 或模板。易错点：只写 `#define MIN(a,b) a<b?a:b` 而不加括号（面试直接扣分）；忽略副作用问题。", "标准写法：\n```c\n#define MIN(a, b) ((a) < (b) ? (a) : (b))   /* 返回两个参数中较小者 */\n```\n说明：①外层括号与每个参数的括号都不能省——'标准'宏的含义就是任何上下文（如 `2*MIN(3,4)`）展开后优先级都不出错；②参数出现两次，`MIN(i++, j)` 这类带副作用的实参会多次求值；③C++ 更推荐 std::min 或模板，C 可用 static inline 函数替代。"),
    51: ("浮点数按二进制近似存储（如 0.1 不能精确表示），运算还会累积舍入误差，'恰好等于零'几乎永远不成立，写 `x == 0` 会漏判实际为零的量；正确做法是判断绝对值小于一个精度阈值：`fabs(x) < eps`，或等价写成区间 `x > -eps && x < eps`。阈值按精度与量级选取：float 常用 1e-6~1e-5，double 可用 1e-9~1e-12；比较两个'接近'的量而不是零时，用 `fabs(x - y) < eps` 或相对误差 `fabs((x-y)/y) < eps`。易错点：直接用 == 0 比较；阈值选得过小（滤不掉误差）或过大（把有效小量误判为零）；忘记包含 <math.h>。", "判断语句（不能写 x == 0）：\n```c\n#include <math.h>\n\n/* 判断 float x 是否与'零值'近似相等 */\nint is_float_zero(float x)\n{\n    if (fabs(x) < 1e-6) {\n        return 1;                  /* 绝对值小于精度阈值：视为 0 */\n    }\n    return 0;\n}\n```\n等价写法：`if (x > -1e-6 && x < 1e-6)`。要点：①浮点有表示误差与累积误差，只能按精度阈值判断；②阈值按实际精度选择：float 一般 1e-6~1e-5、double 用 1e-9~1e-12；③比较两个接近的量用 `fabs(x - y) < eps` 或相对误差 `fabs((x-y)/y) < eps`；④需包含 <math.h>。"),
    58: ("对称性是本题最快解法：网络 = 外圈三角形（A-B、B-C、C-A 各 10K） + 内部星形（A、B、C 各经 10K 汇到中心 D）。①A-B 间：由对称性 C、D 两点电位相同，C-D 间无电流、可先断开；等效为 A-B 直连的 10K、经 C 的 20K、经 D 的 20K 三条支路并联：R_AB = 1/(1/10+1/20+1/20) = 5 KΩ。②A-D 间：同理 B、C 等电位、B-C 间无电流可断开；经 B 的 20K 与经 C 的 20K 并联得 10K，再与直连 A-D 的 10K 并联：R_AD = 10K∥10K = 5 KΩ。也可用 △-Y 变换验证：内部 10K 星形（中心 D 浮空）等效为 30K 三角形，与外部 10K 三角形并联后每对节点间为 (20/3)K ∥ 20K = 5K。易错点：无视对称/电桥结构直接硬套串并联；漏掉'等电位点可先断开'这一步。", "结果：A-B 间 5 KΩ；A-D 间 5 KΩ。\n推导：①A-B 间——对称性使 C、D 等电位（C-D 间无电流，可断开），等效为三条支路并联：A-B 直连 10K、经 C 的 10K+10K=20K、经 D 的 10K+10K=20K；R_AB = 1/(1/10+1/20+1/20) = 5 KΩ。②A-D 间——对称性使 B、C 等电位（B-C 间可断开），经 B 的 20K 与经 C 的 20K 并联得 10K，再与直连 A-D 的 10K 并联：R_AD = 5 KΩ。验证：内部星形（D 浮空）经 △-Y 变换等效为 30K 三角形，与外部 10K 三角形并联，每对节点间 (20/3)K ∥ 20K = 5 KΩ。"),
    75: ("两个术语的区分全在 const 与 * 的相对位置——'const 靠谁谁只读'：const 在 * 左侧管的是所指对象（内容只读），在 * 右侧管的是指针本身（指向只读）。读声明从变量名向外读：`const int *p` 读作'p 是指针、指向 const int'；`int *const p` 读作'p 是常量指针、指向 int'。指针常量定义时必须初始化（之后不能改指向），常量指针可以改指向；组合形式 `const int *const p` 两者都只读。函数参数中常用 `const int *p` 表示'不修改实参所指内容'的输入指针。易错点：把两者名字对调；忘记指针常量必须初始化；误答'const int *p 中 p 也不能改'（其实可以改指向）。", "代码形式与区别：\n```c\nint x = 1, y = 2;\n\n/* ①常量指针（指向常量的指针）：不能改 *p，但 p 可改指向 */\nconst int *p1 = &x;      /* 等价写法：int const *p1 = &x; */\np1 = &y;                 /* 合法：p1 改指向 */\n/* *p1 = 3; */           /* 非法：不能通过 p1 修改所指对象 */\n\n/* ②指针常量（指针本身是常量）：p 不可改指向（定义时须初始化），*p 可改 */\nint *const p2 = &x;\n*p2 = 3;                 /* 合法：修改所指对象的值 */\n/* p2 = &y; */           /* 非法：不能改指向 */\n\n/* ③组合形式：指针与所指对象都只读 */\nconst int *const p3 = &x;\n/* *p3 = 3;  p3 = &y; */ /* 二者均非法 */\n```\n判读口诀：从变量名向外读（右左法则），或'const 靠谁谁只读'——`const int *p` 管所指内容、`int *const p` 管指针本身。\n补充：指针常量定义时必须初始化；函数参数中 `const int *p` 常用于表示不修改实参所指内容。"),
    124: ("按键电路是'上拉 + 按下接地'：节点平时被 R65（4.7K）上拉到 3V3——读到高；按下 K2 时节点直接接 GND——读到低，所以'按下读到低电平'。C61（104=0.1µF）与上拉电阻组成 RC 低通，吸收机械触点抖动的毛刺（硬件去抖），软件仍可配合延时二次确认。该 IO 应配置为输入（上拉或浮空）——绝不能配置为输出，否则按下时与 GND 直接冲突。易错点：答'按下读到高'（把上拉方向记反）；漏掉去抖电容的作用。", "读到低电平。依据：按键接在 IO（PC13）与 GND 之间，节点由 R65（4.7K）上拉到 3V3——松开时被上拉为高电平；按下时 IO 直接接地，故读到低电平。C61（104=0.1µF）与上拉电阻构成 RC 滤波，用于硬件消抖（吸收触点抖动的毛刺）；软件可再配合延时二次确认。该引脚应配置为输入模式（上拉/浮空），不能配置为输出。"),
    125: ("这是 NPN 三极管（SS8050）低侧开关：发射极接地、负载在集电极——LED 阳极接 +5V、阴极经限流电阻 R20（100Ω）接集电极，驱动信号经 R23（1k）加到基极。高电平时 VBE 正偏（约 0.7V）→ 三极管饱和导通 → 电流 +5V→LED→R20→三极管→GND，LED 点亮；低电平时 VBE=0、截止、不亮。R23 限制基极电流、R20 限制 LED 电流；若换成 PNP 高侧开关则高低电平关系相反。易错点：答'低电平点亮'（NPN/PNP 或高/低侧弄反）；漏掉发射结正偏→饱和导通的推导。", "输出高电平点亮。电路为 NPN（SS8050）低侧开关：LED 阳极接 +5V、阴极经 R20（100Ω）接集电极，发射极接地；驱动信号经 R23（1k）接基极。高电平时 VBE 正偏（约 0.7V）→ 三极管饱和导通，电流经 +5V→LED→R20→三极管→GND，LED 点亮；低电平时截止、LED 不亮。R23 限制基极电流，R20 限制 LED 电流；若换成 PNP 高侧开关，高低电平关系相反。"),
    131: ("区分要点是电流流向与引脚电平：拉电流（source）——IO 输出高电平，电流从 IO 流出、经负载回到 GND（负载接在 IO 与 GND 之间）；灌电流（sink）——IO 输出低电平，电流从电源经负载灌入 IO、再流入内部地（负载接在电源与 IO 之间）。工程含义：多数 MCU 灌电流能力≥拉电流能力（如 51 的 P0 口灌电流可达 10~20mA、拉电流极小需外接上拉），所以 LED、蜂鸣器常用'低电平有效'的灌电流驱动；STM32 两者相近（单脚约 ±8~±20mA），但仍受单脚与整片总电流上限约束。易错点：两者名字对调；只讲大小不讲流向；忽略整片总电流限额。", "①拉电流（source）：IO 输出高电平，电流从 IO 流出、经负载回到 GND（负载接在 IO 与 GND 之间），IO 向负载'拉出'电流；②灌电流（sink）：IO 输出低电平，电流从电源经负载灌入 IO 再流入内部地（负载接在电源与 IO 之间），IO'吸收'电流。工程要点：多数 MCU 灌电流能力≥拉电流能力（例如 51 的 P0 口灌电流可达 10~20mA、拉电流极小需外接上拉），所以 LED、蜂鸣器常用'低电平有效'的灌电流驱动；STM32 两者相近（单脚约 ±8~±20mA），还要满足单脚与整片总电流上限。"),
    132: ("分压电路的核心是串联电阻上的电压按阻值比例分配：电流 I = VCC/(R1+R2) 流过两个电阻，V1（R2 上的电压）= I×R2 = VCC×R2/(R1+R2)。代入 3.3V、10K、20K：V1 = 3.3×20/30 = 2.2V。要点：分子必须放'取样点所跨'的电阻（本题 R2 是下臂、接地侧）——这是最常见错误；也可用'下臂越大分压越高'快速自查。延伸：STM32 常用分压把较高电压降到 ADC 量程内，注意分压会引入静态功耗且源阻抗要与 ADC 输入阻抗匹配。", "V1 = 2.2V。推导：串联分压 V1 = VCC × R2/(R1+R2) = 3.3 × 20/(10+20) = 2.2V（R2 为下臂、接地侧电阻，V1 取它两端的电压）。"),
    137: ("判断 MOS 管看三处：①衬底（箭头）方向——箭头由衬底指向沟道内部是 N 沟道，指向外是 P 沟道（本图为 N 沟道）；②引脚——水平引出线是栅极 G（1 脚），另两脚是漏极 D 与源极 S（箭头标在源极侧），本图 2 脚为 D、3 脚为 S；③增强/耗尽型看沟道线——断续为增强型、整条实线为耗尽型。答题要把'类型 + 三引脚'写全。易错点：D/S 记反（可借'箭头在源极侧'记忆）；只看箭头不看沟道线。", "N 型 MOS 管；1 脚为栅极（G）、2 脚为漏极（D）、3 脚为源极（S）。判定依据：箭头由衬底指向沟道内部 → N 沟道；水平引出线是栅极 G，上下两脚分别为 D、S（箭头标在源极一侧）；沟道线断续为增强型、整条为耗尽型。"),
    139: ("判据只有一条：放大状态要求发射结正偏、集电结反偏（NPN 中 UB>UE 且 UC>UB；发射结电压约 0.7V 才算正偏）。逐组核对：A 组 C=+2V、B=+0.7V、E=0V——UBE=0.7V 正偏、UCB=1.3V 反偏，放大；B 组 C=+12V、B=+2V、E=+3V——UBE=-1V 反偏，截止；C 组 C=+10.3V、B=+10.75V、E=+10V——UBE=0.75V 正偏但 UB>UC（集电结正偏），饱和；D 组 C=0V、B=-5.3V、E=-6V——UBE=0.7V 正偏、UCB=5.3V 反偏，放大。所以答案是 A、D。易错点：只看发射结（C 组会误判为放大）；不比较 C 与 B 的电位关系。", "放大状态的是 A、D。判据：发射结正偏（UBE≈0.7V，NPN 中 UB>UE）且集电结反偏（UC>UB）。逐组：A 组 UBE=0.7V 正偏、UCB=1.3V 反偏 → 放大；B 组 UBE=-1V 反偏 → 截止；C 组 UBE=0.75V 正偏但集电结正偏（UB>UC）→ 饱和；D 组 UBE=0.7V 正偏、UCB=5.3V 反偏 → 放大。"),
    147: ("思路是'头插法逆置'：先处理空链表/单节点（直接返回），再把原头节点 head 的 next 断开——它成为逆置链表的尾；随后每轮把当前节点 p 从原链摘下、接到已逆置链表的头部：保存旧头（temp1=head）、头指针前移（head=p）、保存当前节点并先走下一步（temp2=p; p=p->next）、最后反转指针（temp2->next=temp1）。循环到 p==NULL 结束，返回 head 即新链头。复杂度 O(n) 时间、O(1) 空间。题面 Struct 应为 struct（笔误，完整答案中已修正）。易错点：③④两空顺序（必须先保存后继再反转指针，否则丢链）；②空写错（写成 p->next 会在尾节点越界）。", "填空：① `|| head->next==NULL`　② `p != NULL`　③ `head = p`　④ `temp2->next = temp1`。\n补全后的完整函数（已修正题面 Struct 笔误）：\n```c\nstruct node *reverse(struct node *head)\n{\n    struct node *p, *temp1, *temp2;\n    if (head == NULL || head->next == NULL)\n        return head;                 /* ① 空链表或单节点：直接返回 */\n    p = head->next;\n    head->next = NULL;               /* 原头成为逆置链表的尾 */\n    while (p != NULL)                /* ② 还有未处理节点 */\n    {\n        temp1 = head;                /* 保存已逆置链表的旧头 */\n        head = p;                    /* ③ 新头前移到当前节点 */\n        temp2 = p;\n        p = p->next;                 /* 先保存后继，再反转指针 */\n        temp2->next = temp1;         /* ④ 当前节点接到旧头之前（头插） */\n    }\n    return head;\n}\n```\n说明：头插法逆置，时间复杂度 O(n)、空间复杂度 O(1)。"),
    179: ("配置思路：按键与上拉电阻都在外部（PA8 经 R0=10K 上拉到 VCC），所以 PA8 应配置为输入模式——外部已有上拉，内部可配'浮空输入'（让外部上拉决定电平），想增强抗干扰也可再开内部上拉（与外部并联、阻值略降、电平不变）；读取逻辑为松开高、按下低。绝不能配成输出：按下时输出高会与 GND 形成大电流；若该脚被复用为其它外设，也要先释放复用。宏名按所用库写：HAL 为 GPIO_MODE_INPUT（浮空配 GPIO_NOPULL、上拉配 GPIO_PULLUP）；F1 标准库浮空为 GPIO_Mode_IN_FLOATING、上拉为 GPIO_Mode_IPU。易错点：写'输出/复用'；漏掉松开/按下的电平逻辑。", "配置为输入模式（GPIO_MODE_INPUT）。理由：外部已有 R0=10K 上拉到 VCC，内部可配浮空输入、由外部上拉决定电平（HAL：GPIO_MODE_INPUT + GPIO_NOPULL；F1 标准库：GPIO_Mode_IN_FLOATING）；若想增强抗干扰也可开内部上拉（HAL：GPIO_MODE_INPUT + GPIO_PULLUP；F1 标准库：GPIO_Mode_IPU）。电平逻辑：按键松开时被上拉为高、按下时接通 GND 为低。注意：绝不能配置为输出（按下时与外部驱动冲突、产生大电流）。"),
    180: ("原理是 ADC 测'对地电压'再用分压公式：R1 为上臂、Rx 为下臂，节点（AD 引脚）电压 V_AD = VCC × Rx/(R1+Rx)；ADC 的转换关系是 AD_Value = 满码 × V_AD/VREF，12 位满码为 4095，本题 VREF=VCC，代入得 AD_Value = 4095 × Rx/(10k+Rx)（整数量化向下取整）。重要结论：该接法下采样值与 VCC 无关（分子分母中的 VCC 约掉，VCC 波动不影响读数）——这是分压式采样的优点，也是常考加分点。易错点：Rx/(R1+Rx) 与 R1/(R1+Rx) 颠倒；满码写成 4096 或 65535；漏掉'与 VCC 无关'的分析。", "V_AD = VCC × Rx/(R1+Rx) = 3.3 × Rx/(10k+Rx)（单位 V）；AD_Value = 4095 × V_AD/VCC = 4095 × Rx/(10k+Rx)（向下取整）。说明：R1 为上臂、Rx 为下臂；12 位 ADC 满码为 4095；若 ADC 参考电压与 VCC 一致，则 AD_Value 只取决于电阻比值、与 VCC 无关（VCC 波动不影响读数）。"),
    196: ("LED 必须串联限流电阻，否则电流失控烧 LED；计算用回路电压方程：电阻压降 = VCC - VF，回路电流 = IF，故 R = (VCC - VF)/IF = (5-2)/10mA = 300Ω。选型用标称值：300Ω 或 330Ω（电流略小、稍暗）。功耗校验：P = IF²×R = (10mA)²×300Ω = 0.03W，1/4W（0.25W）电阻裕量充足。易错点：忘记减 VF（直接用 5V/10mA 得 500Ω）；单位换算错；不做功耗校验。", "限流电阻 R = 300Ω。计算：R = (VCC - VF)/IF = (5 - 2)V ÷ 10mA = 300Ω（实际可选 300Ω 标称值，或 330Ω 稍暗）。功耗校验：P = I²R = (10mA)² × 300Ω = 0.03W，1/4W 电阻即可。限流电阻必须串联在 LED 回路中，否则电流失控会烧 LED。"),
    197: ("电路是反相加法器：两输入经 R1、R2 接到反相端，反相端'虚地'（同相端经 R3 接地、由虚短使反相端电位≈0V），由虚断，流入节点的电流等于流过反馈电阻 R4 的电流：I = U1/R1 + U2/R2 = 0.4/20k + 0.8/20k = 20µA + 40µA = 60µA；输出 UO = -I×R4 = -60µA×30kΩ = -1.8V。R3 是平衡电阻（减小偏置电流引起的误差）、不参与计算；±6V 供电下 -1.8V 远未饱和。易错点：忘掉反相的负号；把 R3 算进增益；不核对输出摆幅。", "UO = -1.8V。推导：反相加法器，反相端虚地（≈0V，由虚短），虚断下流入电流 I = U1/R1 + U2/R2 = 0.4V/20kΩ + 0.8V/20kΩ = 20µA + 40µA = 60µA；UO = -I × R4 = -60µA × 30kΩ = -1.8V。R3 为平衡电阻、不参与计算；±6V 供电下 -1.8V 未饱和。"),
    200: ("Q1（MMBT3906，PNP）构成高侧开关：发射极接 VCC_AC，基极经 R1（10K）上拉到 VCC_AC、经 R2（1K）接 BACK3，因此基极电位随 BACK3 变化、整体是'反相'关系。①BACK3 为低（≈0V）时，基极被 R2 拉低（分压约 VCC_AC×1K/(1K+10K)），VEB≈0.91×VCC_AC > 0.7V，PNP 导通，ACC3 被拉到高电平（≈VCC_AC）；②BACK3 为高（与 VCC_AC 同域）时 VEB≈0V，PNP 截止，ACC3 失去驱动、被负载/下级泄放为低电平。C1、C2 为输出滤波电容；R1 保证默认截止（BACK3 悬空时 VEB≈0）。易错点：PNP 导通条件写成 VBE>0.7V（应为发射结正偏 VEB>0.7V）；把反相关系答成同相。", "BACK3 为高电平时 ACC3 为低电平；BACK3 为低电平时 ACC3 为高电平（≈VCC_AC）。原理：Q1（MMBT3906，PNP）为高侧开关，发射极接 VCC_AC、基极经 R1（10K）上拉到 VCC_AC 并经 R2（1K）接 BACK3。①BACK3 低时基极被拉低，VEB≈0.91×VCC_AC > 0.7V，PNP 导通 → ACC3 输出高电平；②BACK3 高时 VEB≈0，PNP 截止 → ACC3 被负载泄放为低电平。R1 保证默认截止；C1、C2 为输出滤波电容。"),
    201: ("ADC 采样的是'对地电压'：节点在 R2 与 R1 之间、R1 一端接地，所以测到的就是 R1（下臂）两端的电压。VIN 经 R2、R1 串联分压：V_ADC = VIN × R1/(R1+R2)；R2 起分压/限流与保护作用。工程延伸：①分压电阻取值要与 ADC 输入阻抗匹配（源阻抗过大影响采样精度，必要时加电压跟随器缓冲）；②取值折衷——太大易受噪声与输入阻抗影响，太小则静态功耗大；③采样点常加 RC 滤波与钳位保护。易错点：答'采样 R2 两端'（分子分母颠倒）——R1 接地端正是 ADC 的参考点。", "采样的是 R1 两端的电压（ADC 节点位于 R2 与 R1 之间）。表达式：V_ADC = VIN × R1/(R1+R2)。依据：VIN 经 R2、R1 串联分压，ADC 测量的是节点对地电压，R1 一端接地、一端接节点，所以采样值由 R1 上的分压决定；R2 起串联分压/限流作用。工程提示：分压电阻取值要与 ADC 输入阻抗匹配（必要时加电压跟随器缓冲）；采样点常加 RC 滤波与钳位保护。"),
    208: ("关键是'其余灯不变'——不能对整个 P0 赋值，只能操作 bit3：`P0 ^= (1 << 3)` 用异或只翻转 P0.3（其它位异或 0 不变），每 500ms 翻转一次就得到'亮 500ms、灭 500ms'（周期 1s）。用 `P0 |= (1<<3)` 只能常亮、`P0 &= ~(1<<3)` 只能常灭，都实现不了亮灭交替。易错点：写成 `P0 = (1 << 3)`（其它 7 盏灯被清 0）；用错运算符；把 500ms 当成亮灭总周期（翻转一次只是半周期）。延伸：要求'初始亮灭状态确定'时可在循环前先明确置位或清零。", "完整主程序如下（设环境已提供 P0 与 delayms，且 P0 已配置为输出）：\n```c\nint main(void)\n{\n    while (1)\n    {\n        P0 ^= (1 << 3);     /* 灯4 对应 P0.3：异或翻转该位，其余灯不变 */\n        delayms(500);       /* 每 500ms 翻转一次，亮/灭各 500ms */\n    }\n    return 0;\n}\n```\n要点：①(1<<3) 生成只含 bit3 的掩码 0x08，异或后仅翻转灯 4；②用 ^=（异或）而非直接赋值，才能'其余灯不变'；③每 500ms 翻转一次即形成 1s 周期的亮灭循环。"),
    209: ("流水灯的本质是'单灯掩码循环移动'：`1 << i` 生成只亮第 i 盏灯的掩码（高电平点亮），i 从 0 到 7 循环即可依次点亮 8 盏，每步延时决定流速。变体：①低电平点亮时改为 `P0 = ~(1 << i)`（可用 & 0xFF 限位）；②来回式流水在 i=7 后反向循环；③循环移位 `P0 = (P0 << 1) | (P0 >> 7)` 让亮灯首尾衔接。易错点：写成 `P0 = i`（乱亮多盏）；忘记延时（只看到常亮）；取反时不限位（显式 & 0xFF 更清晰）。", "完整主程序如下（高电平点亮、每盏 300ms）：\n```c\nint main(void)\n{\n    while (1)\n    {\n        for (int i = 0; i < 8; i++)\n        {\n            P0 = (1 << i);     /* 第 i 盏灯亮（高电平点亮） */\n            delayms(300);      /* 每盏保持 300ms */\n        }\n    }\n    return 0;\n}\n```\n变体：①低电平点亮改为 `P0 = ~(1 << i);`（可用 & 0xFF 限位）；②来回式流水可在 i=7 后反向循环；③循环移位 `P0 = (P0 << 1) | (P0 >> 7);` 让亮灯首位衔接。要点：(1<<i) 生成单灯掩码、循环 8 次、每步延时。"),
    264: ("三种操作都基于掩码 `1 << 3`（=0x08，只含 bit3）：置位用'或'——x|0=x、x|1=1，其它位与 0 相或保持、bit3 变 1；清位用'与取反掩码'——`~(1 << 3)` = 0xF7，其它位与 1 相与保持、bit3 与 0 相与变 0；取反用'异或'——x^0=x、x^1=~x，其它位异或 0 保持、bit3 翻转。对硬件寄存器做读-改-写时要注意原子性（中断也操作同一寄存器会丢更新）：先关中断，或用位带/BSRR 等硬件置位复位机制。易错点：清位写成 `a &= (1 << 3)`（直接清掉其它位）；三种运算符记混。", "三段操作（放进完整函数中展示）：\n```c\n/* 设 a 为 8 位可读写变量；三段操作分别独立 */\nvoid a_bit3_ops(void)\n{\n    a |=  (1 << 3);     /* ① 置位：bit3 变 1，其余位不变 */\n    a &= ~(1 << 3);     /* ② 清位：bit3 变 0，其余位不变 */\n    a ^=  (1 << 3);     /* ③ 取反：bit3 翻转，其余位不变 */\n}\n```\n掩码 `1<<3` = 0x08 只含 bit3，三种复合赋值都不影响其它位。对硬件寄存器连续操作时注意原子性（中断场景先关中断或用位带/BSRR）。"),
    334: ("摘链分两种情况——摘的是链头（r==NULL）还是中间/尾部节点：前者要改'指向链头的指针'，所以第一空 `*list = l->next;`（list 是头指针的指针，这样写才能改变调用者看到的链头）；后者改前驱的 next：`r->next = l->next;`，让前驱直接跳过 l。摘链完成后节点 l 若不再使用，一般还要 free(l)（内存池实现则归还池），否则内存泄漏。易错点：链头分支写成 `list = l->next;`（只改局部副本、调用者的链头没变）；忘记 free。", "填空：① `*list = l->next;`　② `r->next = l->next;`。\n按题意补全的完整函数（list 为头指针的指针，r 为前驱、摘链头时传入 NULL）：\n```c\nvoid remove_node(struct node * *list, struct node *r, struct node *l)\n{\n    if (r == NULL) {\n        *list = l->next;      /* ① 摘的是链头：头指针后移 */\n    } else {\n        r->next = l->next;    /* ② 前驱直接指向 l 的后继，跳过 l */\n    }\n    free(l);                  /* 摘链后如不再使用该节点，释放以免泄漏 */\n}\n```\n说明：r 初始为 NULL 表示 l 是链头；否则 r 是 l 的前驱。"),
    362: ("判断运放电路类型三看：输入信号接哪个输入端、反馈电阻怎么连、另一个输入端如何接地。①输入经电阻接反相端、反馈电阻跨接反相端与输出（同相端经电阻接地）→ 反相比例放大，Vout = -(Rf/R1)·Vin；②输入经电阻接同相端（反相端经电阻接地、反馈跨接）→ 同相比例放大，Vout = (1+Rf/R1)·Vin；③两路输入各经电阻分别接两个输入端（且两端都有对地电阻）→ 差分（减法）放大，Vout = (Rf/R1)·(V2-V1)。答题先按图认定类型、再写对应公式；能代入图中电阻比值算出具体倍数更好。易错点：反相/同相公式记混（同相多一个 1+）；不判图直接背公式。", "从图中可见：信号经 R1 接反相端（1 脚）、反馈电阻 R2 跨接反相端与输出（3 脚），R3 接同相端（2 脚）且标注 Vin。按三种典型应用对照作答：①反相比例放大（输入经电阻接反相端、反馈跨接）——Vout = -(Rf/R1)·Vin；②同相比例放大（输入接同相端）——Vout = (1+Rf/R1)·Vin；③差分（减法）放大（两路输入各经电阻接两端）——Vout = (Rf/R1)·(V2-V1)。以原图为准写出所选类型与公式，能代入电阻比值算出具体倍数更好。"),
    363: ("电流镜的核心是'镜像'：T0 的集电极与基极短接（二极管接法）构成参考支路，T1 的基极与 T0 相连、两管特性相同所以 UBE 相等；由三极管的正向控制关系（UBE 相同时集电极电流相同），T1 便复制 T0 的集电极电流。β→∞ 时基极电流 IB0≈IB1≈0，参考支路里 IC0≈IR，于是 IC1≈IC0≈IR——T1 支路成为由 IR 设定的恒流源（对 T1 集电极电压不敏感，因为 UBE 由参考支路固定）。实际 β 有限时两管基极电流由参考支路提供、存在小误差：IC1≈IR/(1+2/β)。用途：给差分对/放大器提供稳定偏置电流、做电流源负载。易错点：忘记'集电结短接'前提；β 有限时误差方向说反。", "这是电流镜电路，结论：IC1 ≈ IR。机理：T0 的集电极与基极短接（二极管接法）作参考支路；两管特性相同、UBE 相等，基极相连使 T1 复制 T0 的电流。β→∞ 时基极电流可忽略（IB0≈IB1≈0），IC0≈IR，故 IC1 = IC0 ≈ IR，T1 支路构成恒流源、电流由 IR 设定。实际 β 有限时存在小误差：IC1 ≈ IR/(1+2/β)（两管基极电流均由参考支路提供）。"),
    365: ("这是两级级联的电源开关，解决'MCU 无法直接驱动高侧管'的问题：MCU_IO 经限流/RC（R4、C1）驱动 Q2（低侧 NPN/NMOS）导通或截止；Q2 导通时把 Q1（高侧 PNP/PMOS）的基极/栅极电位经 R2 拉低，Q1 随之导通，VCC 经 Q1 送到 VOUT；Q2 截止时 R1 把 Q1 的基极/栅极上拉到高电平，Q1 关断、VOUT 断电。即：MCU_IO 高 → Q2 通 → Q1 通 → 输出上电，MCU_IO 低 → 输出断电，整体是'正逻辑'控制。元件作用：R1 默认关断上拉、R2 偏置/限流、R4+C1 构成 MCU_IO 的 RC 滤波（抑制瞬态/干扰）；D1+EN1 支路可作为使能或强制关断。易错点：把 Q1/Q2 高低侧说反；漏掉 R1 的默认关断作用。", "两级级联的电源开关：①MCU_IO 输出高 → 经限流电阻驱动 Q2（低侧 NPN/NMOS）导通 → 把 Q1（高侧 PNP/PMOS）的基极/栅极经 R2 拉低 → Q1 导通 → VCC 经 Q1 送到 VOUT（供电接通）；②MCU_IO 输出低 → Q2 截止 → R1 把 Q1 的基极/栅极上拉到高电平 → Q1 关断 → VOUT 断电。元件作用：R1 保证默认关断；R2 为偏置/限流；R4 与 C1 构成 MCU_IO 的 RC 滤波（抑制瞬态）；D1+EN1 支路可作为使能或强制关断。要点：Q1 高侧、Q2 低侧，低侧管把 MCU 的逻辑电平'翻译'成高侧管的驱动电平。"),
    379: ("三种门看框内的识别标志：标 ≥1 的是或门（OR，'有 1 则 1'）；标 & 的是与门（AND，'全 1 才 1'）；标 =1 的是异或门（XOR，'相异为 1'）。这是 IEC 标准符号：≥1 表示输入中至少一个为 1 输出就有效；=1 表示输入中 1 的个数恰为 1（对两输入即'相异'）时输出有效。答题把符号与名称一一对应写上，写出口诀或真值表可加分。易错点：=1 与 ≥1 混淆；把 =1 当与门。", "三种门符号对应关系：①框内标 ≥1 → 或门（OR）；②框内标 & → 与门（AND）；③框内标 =1 → 异或门（XOR）。口诀：有 1 则 1 是或、全 1 才 1 是与、相异为 1 是异或。"),
    380: ("英文题干拆解：mpu641 是 machine 类型的结构体指针（a pointer of type machine），题目要求把 NULL 赋给它的 memory 字段。结构体指针访问成员用箭头运算符 '->'（`mpu641->memory` 等价于 `(*mpu641).memory`）；赋值用单等号 =（双等号 == 是判断相等）；NULL 表示空指针。若 mpu641 是结构体变量而非指针，才用点运算符 `mpu641.memory`。易错点：指针误用点运算符；误写 == NULL（变成比较不是赋值）。", "命令：`mpu641->memory = NULL;`。说明：mpu641 是结构体指针，访问成员用箭头运算符 `->`（等价于 `(*mpu641).memory`）；赋值用单等号 `=`，双等号 `==` 才是判断相等；若 mpu641 是结构体变量而非指针，则应写 `mpu641.memory = NULL;`。"),
    386: ("三目宏的完整形态要'两层括号'：每个参数各一层 + 整体一层，否则调用处展开后被优先级打乱（如 `MIN(x & 1, y)`）；三目条件与宏名一致（取最小用 <，取最大改用 >）。宏是文本替换、参数出现两次，`MIN(i++, j)` 这类带副作用的实参会被多次求值而出错；C 可用 static inline 函数、C++ 用 std::min 替代。易错点：括号不全（主要扣分点）；把宏参数当函数实参理解。", "宏定义：\n```c\n#define MIN(a, b) ((a) < (b) ? (a) : (b))\n```\n要点：①两个参数各加括号、整体再加一层，防止调用处优先级出错（如 `MIN(x & 1, y)`）；②宏会重复求值，实参带 i++ 等副作用时结果错误；③工程上可用 `static inline int min(int a, int b) { return a < b ? a : b; }` 或 C++ 的 std::min 替代。"),
}

if __name__ == "__main__":
    need = [6, 7, 8, 29, 32, 33, 50, 51, 58, 75, 124, 125, 131, 132, 137, 139,
            147, 179, 180, 196, 197, 200, 201, 208, 209, 264, 334, 362, 363,
            365, 379, 380, 386]
    assert sorted(NEW.keys()) == need, "题号集合不符"
    code_nums = {6, 29, 32, 33, 50, 51, 75, 147, 208, 209, 264, 334, 386}
    bad = []
    for n, (a, b) in NEW.items():
        if "\n" in a or "\r" in a or "**" in a or a.strip() != a:
            bad.append((n, "ana"))
        if "\r" in b or "**" in b or b.strip() != b:
            bad.append((n, "ans"))
        if n in code_nums and "```c" not in b:
            bad.append((n, "缺代码"))
    print("题号齐全 OK，共", len(NEW), "题", ("异常: " + str(bad)) if bad else "")
